const item=$input.first();
try {
 const ruc=String(item.json.RUC??'').trim(),expediente=String(item.json.Folio??'').trim().toLowerCase(),fuenteReferencia=String(item.json['Fuente de referencia']??'').trim();
 if(!/^\d{11}$/.test(ruc)||! /^[a-f0-9]{32}$/.test(expediente))throw Error('Revisa el RUC y el folio de 32 caracteres de la FASE 2.');
 if(fuenteReferencia.length>500)throw Error('La fuente de referencia debe tener hasta 500 caracteres.');
 const keys=Object.keys(item.binary??{});if(keys.length<1||keys.length>2)throw Error('Adjunta tu propuesta y, opcionalmente, una referencia.');
 let total=0;const archivos=[];
 for(const key of keys){
  const categoria=/^Propuesta(?:_|$)/.test(key)?'propuesta':/^Referencia(?:_|$)/.test(key)?'referencia':null;
  if(!categoria)throw Error('Campo de archivo desconocido.');
  const raw=await this.helpers.getBinaryDataBuffer(0,key);total+=raw.length;
  if(!raw.length||raw.length>5*1024*1024||total>10*1024*1024)throw Error('Máximo 5 MB por archivo y 10 MB por envío.');
  archivos.push({categoria,nombre:item.binary[key].fileName,contenido:raw.toString('base64')});
 }
 if(archivos.some(f=>f.categoria==='referencia')&&!fuenteReferencia)throw Error('Indica la procedencia de la propuesta de referencia.');
 return [{json:{listo:true,ruc,expediente,fuenteReferencia,archivos}}];
}catch(e){return [{json:{listo:false,resultado:'DOCUMENTOS_INVALIDOS',mensaje:e.message}}];}

